VEC_NAMES = {
    0x00: "vec_reset__c_int00",
    0x01: "vec_int0_display",
    0x02: "vec_int1_tv30",
    0x03: "vec_int2_comm",
    0x04: "vec_int3_atod",
    0x05: "vec_xint0",
    0x06: "vec_rint0",
    0x07: "vec_xint1",
    0x08: "vec_rint1",
    0x09: "vec_tint0",
    0x0A: "vec_tint1",
    0x0B: "vec_dint",
}

def in_mapped(ea):
    return ida_segment.getseg(ea) is not None

def bswap32(v):
    return ((v & 0xFF) << 24) | (((v >> 8) & 0xFF) << 16) | (((v >> 16) & 0xFF) << 8) | ((v >> 24) & 0xFF)

def maybe_make_func(ea):
    if not in_mapped(ea):
        return False
    if ida_funcs.get_func(ea):
        return True
    return bool(ida_funcs.add_func(ea))

def clear_all_names():
    c = 0
    for ea, _nm in list(idautils.Names()):
        ida_name.del_local_name(ea)
        ida_name.del_global_name(ea)
        c += 1
    return c

def apply():
    cleared = clear_all_names()
    named = 0
    vec_named = 0
    vec_funcs = 0
    dp_set = 0

    # Vector labels and targets
    for idx in range(0x40):
        ea = idx
        if not in_mapped(ea):
            continue
        vname = VEC_NAMES.get(idx, f"vec_{idx:02X}")
        ida_name.set_name(ea, vname, ida_name.SN_FORCE)
        vec_named += 1
        target = bswap32(ida_bytes.get_wide_byte(ea))
        tname = f"{vname}_target_{target:08X}"
        if in_mapped(target):
            ida_name.set_name(target, tname, ida_name.SN_FORCE)
            if maybe_make_func(target):
                vec_funcs += 1

    # Resolve DP register index once (IDA 7.x API expects register index).
    dp_reg = ida_idp.str2reg("dp")
    if dp_reg < 0:
        print("[crusnusa-py] warning: could not resolve dp register index; skipping DP marks")

    # Apply DP=0 splits
    for ea in DP0_MARKS:
        if not in_mapped(ea):
            continue
        if dp_reg < 0:
            continue
        ok = ida_segregs.split_sreg_range(ea, dp_reg, 0, ida_segregs.SR_user, False)
        if ok:
            dp_set += 1
        else:
            print(f"[crusnusa-py] dp0 split failed at 0x{ea:08X}")

    # Apply labels
    for ea, nm in LABELS:
        if not in_mapped(ea):
            continue
        ida_name.set_name(ea, nm, ida_name.SN_FORCE)
        named += 1

    # Attach source-macro comments
    for ea, cmt in COMMENTS:
        if not in_mapped(ea):
            continue
        ida_bytes.set_cmt(ea, cmt, 0)

    print(f"[crusnusa-py] cleared={cleared} vectors={vec_named} vec_funcs={vec_funcs} dp0={dp_set} labels={named} comments={len(COMMENTS)}")

apply()
